begin;
select plan(17);
select ok(not has_function_privilege('anon','public.begin_storage_cleanup_run(uuid,text)','execute'),'anonymous cannot start cleanup');
select ok(not has_function_privilege('authenticated','public.begin_storage_cleanup_run(uuid,text)','execute'),'users cannot start cleanup');
select ok(not has_function_privilege('authenticated','public.finish_storage_cleanup_run(uuid,jsonb,boolean)','execute'),'users cannot record results');
select ok(not has_table_privilege('authenticated','private.storage_cleanup_runs','select'),'history private');
select ok(has_function_privilege('service_role','public.begin_storage_cleanup_run(uuid,text)','execute'),'service can start');
select ok(public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000091','edge'),'first run owns lease');
select ok(not public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000092','edge'),'parallel run denied');
select ok(not public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000091','edge'),'replay denied');
select ok(not public.finish_storage_cleanup_run('00000000-0000-4000-8000-000000000092','{"submissions":{"claimed":0,"removed":0,"retry":0},"avatars":{"claimed":0,"removed":0,"retry":0}}'),'different run cannot release');
select throws_ok($$select public.finish_storage_cleanup_run('00000000-0000-4000-8000-000000000091','{"submissions":{"claimed":1,"removed":2,"retry":0},"avatars":{"claimed":0,"removed":0,"retry":0}}')$$,'22023','Invalid cleanup counts','invalid counts rejected');
select ok(public.finish_storage_cleanup_run('00000000-0000-4000-8000-000000000091','{"submissions":{"claimed":1,"removed":0,"retry":1},"avatars":{"claimed":0,"removed":0,"retry":0}}',true),'uncertainty recorded');
select ok(not public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000092','mac'),'uncertainty retains shared lease');
select ok(public.finish_storage_cleanup_run('00000000-0000-4000-8000-000000000091','{"submissions":{"claimed":0,"removed":0,"retry":0},"avatars":{"claimed":0,"removed":0,"retry":0}}'),'finish replay acknowledged');
select is((select state from private.storage_cleanup_runs where id='00000000-0000-4000-8000-000000000091'),'failed','replay cannot rewrite outcome');
update private.storage_cleanup_lease set expires_at=clock_timestamp()-interval '1 second';
select ok(public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000092','edge'),'expired lease reclaimed');
select ok(not public.finish_storage_cleanup_run('00000000-0000-4000-8000-000000000091','{"submissions":{"claimed":0,"removed":0,"retry":0},"avatars":{"claimed":0,"removed":0,"retry":0}}'),'stale owner cannot release new lease');
select ok(not public.begin_storage_cleanup_run('00000000-0000-4000-8000-000000000091','edge'),'old request cannot replay');
select * from finish();
rollback;
